-- A feature-level temporal contract, not DDL generated by document imports.
alter table public.documents
 add column temporal_basis text not null default 'DATED' check(temporal_basis in ('DATED','CURRENT_REVIEWED')),
 add column current_reviewed_at timestamptz;

-- Identify the one legacy ACTIVE-date gate by its catalog definition, not an assumed generated name.
do $$
declare gates text[];
begin
 select array_agg(conname) into gates from pg_constraint
 where conrelid='public.documents'::regclass and contype='c'
  and pg_get_constraintdef(oid) like '%status%'
  and pg_get_constraintdef(oid) like '%effective_from IS NOT NULL%';
 if coalesce(cardinality(gates),0)<>1 then raise exception 'DOCUMENT_TEMPORAL_GATE_AMBIGUOUS'; end if;
 execute format('alter table public.documents drop constraint %I',gates[1]);
end $$;

alter table public.documents add constraint documents_reviewed_temporal_shape check(
 (temporal_basis='DATED' and current_reviewed_at is null) or
 (temporal_basis='CURRENT_REVIEWED' and current_reviewed_at is not null and effective_from is null and effective_to is null
  and document_type in ('FORM','GUIDE','CALENDAR') and (document_type<>'CALENDAR' or academic_year is not null)));
alter table public.documents add constraint documents_active_temporal_review check(
 status not in ('ACTIVE','SUPERSEDED','EXPIRED') or
 (approval_status='APPROVED' and extraction_reviewed and not requires_review and
  (temporal_basis='DATED' and effective_from is not null or temporal_basis='CURRENT_REVIEWED' and current_reviewed_at is not null)));

create function private.guard_document_temporal_review() returns trigger language plpgsql set search_path='' as $$
begin
 if tg_op='UPDATE' and (new.temporal_basis is distinct from old.temporal_basis or new.current_reviewed_at is distinct from old.current_reviewed_at) then
  raise exception 'DOCUMENT_TEMPORAL_REVIEW_IMMUTABLE';
 end if;
 if tg_op='INSERT' and new.temporal_basis='CURRENT_REVIEWED' then
  new.current_reviewed_at:=clock_timestamp();
 end if;
 return new;
end $$;
revoke all on function private.guard_document_temporal_review() from public,anon,authenticated;
grant execute on function private.guard_document_temporal_review() to service_role;
create trigger guard_document_temporal_review before insert or update on public.documents
 for each row execute function private.guard_document_temporal_review();

-- Undated observations cannot establish a timed rule effect, in either direction.
create function private.guard_dated_document_relationship() returns trigger language plpgsql set search_path='' as $$
begin
 if new.relation_type not in ('AMENDS','CANCELS','SUPERSEDES') then return new; end if;
 perform 1 from public.documents where id in (new.source_document_id,new.target_document_id) order by id for share;
 if exists(select 1 from public.documents where id in (new.source_document_id,new.target_document_id) and temporal_basis<>'DATED') then
  raise exception 'DOCUMENT_RELATIONSHIP_REQUIRES_DATED_SOURCE';
 end if;
 return new;
end $$;
revoke all on function private.guard_dated_document_relationship() from public,anon,authenticated;
grant execute on function private.guard_dated_document_relationship() to service_role;
create trigger guard_dated_document_relationship before insert or update on public.document_relationships
 for each row execute function private.guard_dated_document_relationship();

create index documents_current_reviewed_lookup_idx on public.documents(document_family_id,version_stream,current_reviewed_at)
 where temporal_basis='CURRENT_REVIEWED' and is_current and status='ACTIVE';
